\subsection{Instantaneous Bandwidth}\label{subsec:uca_ibw}
We derive \ac{IBW} of the \ac{UCA} following the same procedure as the \ac{ULA} case in Section~\ref{subsec:ula_ibw}. 
\subsubsection{Angle-Domain \ac{IBW}}
Retaining only the tilt term of \eqref{eq:Xi_uca}, the normalized space--frequency gain in \eqref{eqn-ibw-master} reduces to
\begin{equation}\small
g_a(f)
=\left|\frac{1}{N}\sum_{n=1}^{N}
\exp\!\left(j\,\frac{2\pi f}{c}\,R\sin\theta_0\cos\psi_n\right)\right|^2 ,
\label{eq:uca-gtheta-sum}
\end{equation}
\normalsize
which, for large $N$, is the ring average of a linear phase and evaluates to the zeroth-order Bessel form $J_0(\cdot)$ \cite{van2002optimum,10243590}
\begin{equation}\small
g_a(f)
=\left|J_0\!\left(\frac{2\pi f}{c}\,R\sin\theta_0\right)\right|^2 .
\label{eq:uca-gtheta-bessel}
\end{equation}
\normalsize
The angle domain \ac{IBW} is obtained by setting $\eta_\mathrm{uca}=\frac{2\pi f}{c}\,R\sin\theta_0$, where the value of $\eta_\mathrm{uca}$ is obtained as $g_a(\eta_\mathrm{uca})=\rho_{\epsilon}$ for a specific threshold. For the 3dB convention $\rho_\epsilon=0.5$, $\eta_\mathrm{uca}\approx1.126$. Solving for the two-sided frequency offset yields
\begin{equation}
\mathrm{IBW}^{\mathrm{uca}}_{a}
=\frac{c\,\eta_\mathrm{uca}}{\pi R\sin\theta_0} \approx \frac{1.126c\,}{\pi R\sin\theta_0},
\label{eq:uca-ibw-angle}
\end{equation}
which depends only on the elevation angle $\theta_0$ and is independent of the azimuth angle.
\subsubsection{Distance-Domain \ac{IBW}}
Retaining only the curvature term of \eqref{eq:Xi_uca}, the gain in \eqref{eqn-ibw-master} reduces to
\begin{align}\small
g_r(f)
&=\left|\frac{1}{N}\sum_{n=1}^{N}
\exp\!\left(j\,\frac{\pi f}{c}\,\frac{R^2\sin^2\theta_0}{r_0}\,\cos^2\psi_n\right)\right|^2 \notag, 
&\overset{(a)}{\approx}\left|J_0\!\left(\frac{\pi f\,R^2\sin^2\theta_0}{2\,c\,r_0}\right)\right|^2 ,
\label{eq:uca-gr-bessel}
\end{align}
\normalsize
where (a) is derived similarly to the angle domain gain \cite{11498324,10243590}. Solving for the two-sided frequency offset yields the distance-domain \ac{IBW}
\begin{equation}
\mathrm{IBW}^{\mathrm{uca}}_{r}
=\frac{4\,c\,r_0\,\eta_\mathrm{uca}}{\pi R^2\sin^2\theta_0} \approx \frac{4.52\,c\,r_0\,}{\pi R^2\sin^2\theta_0}.
\label{eq:uca-ibw-range}
\end{equation}
\subsubsection{Combined Near-Field \ac{IBW}}
 The combined \ac{IBW} is the minimum of the two \acp{IBW}, expressed as
\begin{equation}
\mathrm{IBW}^{\mathrm{uca}}
=\min\!\left(\frac{1.126c\,}{\pi R\sin\theta_0},\,
\frac{4.52\,c\,r_0\,}{\pi R^2\sin^2\theta_0}\right).
\label{eq:uca-ibw-min}
\end{equation}
The two terms intersect at the crossover range $r_0=R\sin\theta_0/4$. Below this range, the curvature term dominates, making the \ac{IBW} range-limited. Above it, the tilt term dominates, and the \ac{IBW} is governed by \eqref{eq:uca-ibw-angle}.
\subsection{RF Chain Count for the SC UCA}\label{sec-VB}
As shown in Fig. \ref{fig:uca_sc_geom}, the \ac{UCA} is partitioned into $K$ contiguous arcs of angular width $2\pi/K$, each comprising $N_k=N/K$ elements and spanning the arc length $L_k=2\pi R/K=\pi L/K$. The \ac{IBW} in \eqref{eq:uca-ibw-min} does not apply to a single arc because its Bessel kernel results from the full-ring average $\frac{1}{2\pi}\int_{0}^{2\pi}e^{jz\cos\psi}\mathrm{d}\psi=J_0(z)$ over a closed contour. In contrast, a single arc spans only $2\pi/K$ and has two finite endpoints, resulting in the sinc and Fresnel kernels derived for the \ac{ULA} in Section~\ref{subsec:ula_ibw} \cite{10843386}. Accordingly, we characterize the \ac{IBW} of the \ac{SC} \ac{UCA} using \eqref{eq:ibwk}, with the arc-specific geometric parameters replacing those of the \ac{ULA}.
We define $\psi_k^c$ as the mid-angle of the $\nth{k}$ arc and $s=R(\psi_n-\psi_k^c)$ as the arc-length of the $\nth{n}$ element measured from the mid-angle $\psi_k^c$. Substituting $\psi_n=\psi_k^c+s/R$ into \eqref{eq:uca_profile} recasts the element--\ac{UE} distance in terms of the arc-length $s$ 
\begin{equation}\small
d(s)=\sqrt{r_0^{2}+R^{2}-2Rr_0\sin\theta_0\cos\!\big( u_k+s/R\big)},
\ u_k=\psi_k^c-\varphi_0,
\label{eq:uca_ds}
\end{equation}\normalsize
whose value at the arc center is the local range $r_k=d(0)$. Since the elements of an arc are non-collinear, the local angle and distance pair $(\varphi_k, r_k)$ is insufficient to capture the delay spread across the subarray. Instead, we characterize the delay profile using its slope and curvature, obtained from the first and second derivatives of \eqref{eq:uca_ds} evaluated at $s=0$, yielding
\begin{equation}\small
p_k=\frac{r_0\sin\theta_0\sin u_k}{r_k},
\quad
q_k=\frac{r_0\sin\theta_0\cos u_k}{R\,r_k}
-\frac{\big(r_0\sin\theta_0\sin u_k\big)^{2}}{r_k^{3}}.
\label{eq:uca_pq}
\end{equation}\normalsize
The slope $p_k$ replaces $\sin\varphi_k$ and the curvature $q_k$ replaces $\cos^{2}\varphi_k/r_k$ in \eqref{eq:ibwk}, which gives the per-arc \ac{IBW}
\begin{equation}
\mathrm{IBW}_k^\mathrm{uca}=\min\!\left(
\frac{2\etaangle}{\pi}\frac{c}{L_k\,\abs{p_k}},\
\frac{4\etarange^{2}\,c}{L_k^{2}\,\abs{q_k}}\right).
\label{eq:uca_ibwk}
\end{equation}
The minimum \ac{RF} chain count follows from \eqref{eq:Krule} and Algorithm~\ref{alg:rfcount} is evaluated with
$(L_k,p_k,q_k)$. 
\subsection{RF Chain Count for FC UCA}
The distance profile in \eqref{eq:uca_profile} is monotonic in $\cos\psi$, with its minimum at $\psi - \varphi_0=0$ and maximum at $\psi-\varphi_0=\pi$. Both extreme distances lie on the ring for every $r_0$ and $\theta_0$, and therefore, unlike the \ac{ULA}, the \ac{UCA} admits no case split. Writing the extreme distances as
\begin{equation}
d_{\pm}=\sqrt{r_0^2+R^2\pm 2Rr_0\sin\theta_0},
\label{eq:uca_edge}
\end{equation}
the \ac{RF} chain count in \eqref{eq:alpha} reduces to the single closed form
\begin{equation}
\alpha_{\mathrm{uca}}(\theta_0,r_0)=\frac{W}{c}\big(d_+-d_-\big)
=\frac{W}{c}\,\frac{4Rr_0\sin\theta_0}{d_++d_-},
\label{eq:uca_alpha}
\end{equation}
and the minimum \ac{RF} chain count is $K_\mathrm{FC}^{\mathrm{uca}}=\lceil\alpha_{\mathrm{uca}}\rceil$. The two extreme elements are diametrically opposite and separated by the diameter $L=2R$, so the triangle inequality gives $d_+-d_-\le L$. The \ac{UCA} therefore never requires more than $WL/c$ \ac{RF} chains.
\subsubsection{Limiting Cases}
The behavior of $\alpha_{\mathrm{uca}}$ is characterized by four limiting regimes.
\paragraph{FF limit ($r_0\to\infty$)}
As the focal point recedes, the spherical wavefront approaches a planar wavefront and $d_+-d_-\to L\sin\theta_0$. Consequently, \eqref{eq:uca_alpha} reduces to
\begin{equation}
\alpha_{\mathrm{uca}}\xrightarrow[r_0\to\infty]{}\frac{WL\sin\theta_0}{c}.
\label{eq:uca_lim_ff}
\end{equation}
\paragraph{Deep NF limit ($r_0\to0$)}
As the focal point approaches the array center, both extreme path lengths converge to $R$, causing the path length difference to vanish, $\alpha_{\mathrm{uca}}\rightarrow 0$. Unlike the \ac{ULA}, the \ac{UCA}
has no \ac{NF} floor.
\paragraph{Axial boresight ($\theta_0=0$)}
All the antenna elements are equidistant from a focal point located along the axial boresight. Hence, the path-length difference across the aperture vanishes for all ranges, yielding $\alpha_{\mathrm{uca}}\big|_{\theta_0=0}=0$.
\paragraph{Co-planar direction ($\theta_0=90^\circ$)}
When the focus lies in the array plane, the path-length difference reduces to $2r_0$ for $r_0<R$ and saturates at $2R$ for $r_0\ge R$. Hence, the \ac{RF} chain count becomes
\begin{equation}
\alpha_{\mathrm{uca}}\big|_{\theta_0=90^\circ}
=
\frac{2W}{c}
\begin{cases}
r_0, & r_0<R,
R, & r_0\ge R,
\end{cases}
\label{eq:uca_lim_inplane}
\end{equation}
which increases linearly with $r_0$ until reaching $WL/c$ at $r_0=R$, after which it remains constant.
