 \label{fig:example_converge}
\end{figure}
\begin{theorem}[Finite-time stationarity]
\label{theorem:finite}
Consider the gradient sampling update in \eqref{eq:update_H}. Let $L_R$ be the Lipschitz
constant of $R(\bH)$ 
and define
\begin{equation}
 R_{\mathrm{max}}= \max_{\bm\theta\in\Phi_K^N}\mathrm{SNR}(\bm\theta).
\end{equation}
Moreover, we define the partial derivative vector as
\begin{equation}
 \nabla R(\bH)\triangleq
\left(
\frac{\partial R(\bH)}{\partial H_n(\phi)}
\right)_{n=1,\ldots,N,\ \phi\in\Phi_K}.
\end{equation}
Then, for any finite horizon $T\geq 1$ and any positive learning rates
$\{\gamma^t\}_{t=1}^T$, we have
\begin{equation}
\min_{1\leq t\leq T}
\mathbb{E}\!\left[\|\nabla R(\bH^t)\|^2\right]
\leq
\frac{
R_{\mathrm{max}}+L_R NR_{\mathrm{max}}^2\sum_{t=2}^T(\gamma^t)^2
}{
\sum_{t=2}^T\gamma^t
}.
\end{equation}
In particular, by choosing the horizon-dependent constant learning rate, i.e., $\gamma^t=\frac{\eta}{\sqrt{T}}, t=2,\ldots,T$,
for some constant $\eta>0$, we obtain
\begin{equation}
\min_{1\leq t\leq T}
\mathbb{E}\!\left[\|\nabla R(\bH^t)\|^2\right]
\leq
\frac{R_{\max}/\eta+N R_{\max}^2\eta}{\sqrt{T}}
=
O\left(\frac{1}{\sqrt{T}}\right).
\end{equation}
\end{theorem}
\begin{IEEEproof}
The proof follows from the standard finite-time analysis of stochastic
gradient methods; see, e.g.,
\cite[Lemma 4.2 and Theorem 4.10]{bottou2018optimization}.
\end{IEEEproof}
In summary, Theorem \ref{theorem:asymptotic}  establishes the asymptotic first-order stationarity of the proposed gradient bandit algorithm under
Robbins--Monro learning rates, while Theorem \ref{theorem:finite} provides the finite-time stationarity that a horizon-dependent constant learning rate yields the $O(\frac{1}{\sqrt{T}})$ convergence rate. We remark that the convergence results in Theorems \ref{theorem:asymptotic} and \ref{theorem:finite} represent the strongest general conclusion for the proposed gradient sampling algorithm. Since the expected SNR objective induced by the product softmax probability is nonconvex, global optimality cannot be guaranteed. We illustrate this point with a toy example for the case of $N=3$ and $K=4$ in Fig. \ref{fig:example_converge}. Consequently, a regret bound analysis for the gradient sampling algorithm is not available because such an analysis would require a guarantee of global optimality.
